WITH fl AS (SELECT capture_id FROM capture_trust FINAL WHERE trust = 'flagged'), (SELECT tuple(groupArray(id), groupArray(name)) FROM (SELECT id, any(name) AS name FROM spell_names WHERE release = (SELECT max(release) FROM captures) GROUP BY id)) AS sp, m AS (SELECT zone_id AS zone, mob_name AS name, countIfMerge(fights) AS n_fights, uniqExact(capture_id) AS captures, minMerge(level_lo) AS lo, maxMerge(level_hi) AS hi, countIfMerge(hp_n) AS hp, sumIfMerge(delay_n) AS delay, arraySum(sumMapIfMerge(moves).2) AS n_moves, arraySort(arrayDistinct(arrayFilter(c -> c BETWEEN 7 AND 14, arrayMap(k -> k.1, arrayFilter(k -> NOT k.3, sumMapIfMerge(sc_tiers).1))))) AS chains, arrayMap(i -> sp.2[indexOf(sp.1, i)], sumMapIfMerge(results).1) AS taken, arraySum(arrayFilter((n, k) -> k >= 0, sumMapIfMerge(th_kills).2, sumMapIfMerge(th_kills).1)) AS drops, arraySum(sumMapIfMerge(respawns).2) AS n_respawns FROM bestiary_mobs FINAL WHERE capture_id NOT IN fl GROUP BY zone_id, mob_name HAVING n_fights > 0), ag AS (SELECT zone_id AS zone, mob_name AS name, uniqExactIf((mob_id, intDiv(ts_ms, 10000)), kind = 'aggro_recorder' AND clean AND distance IS NOT NULL) AS clean, uniqExactIf((mob_id, intDiv(ts_ms, 10000)), kind IN ('aggro_recorder', 'aggro_party', 'aggro_other')) AS own FROM aggro WHERE capture_id NOT IN fl GROUP BY zone_id, mob_name), ps AS (SELECT zone_id AS zone, mob_name AS name, count() AS passes FROM aggro_passes WHERE capture_id NOT IN fl GROUP BY zone_id, mob_name), seen AS (SELECT DISTINCT zone_id AS zone, mob_name AS name FROM bestiary_looks WHERE capture_id NOT IN fl AND mob_name != ''), z AS (SELECT id, any(name) AS zone_name FROM zone_names GROUP BY id) SELECT k.zone AS zone, any(z.zone_name) AS zone_name, groupArray(tuple(k.name AS name, coalesce(m.n_fights, 0) AS fights, coalesce(m.captures, 0) AS captures, m.lo AS lo, m.hi AS hi, coalesce(m.hp, 0) AS hp, coalesce(m.delay, 0) AS delay, coalesce(m.n_moves, 0) AS moves, coalesce(m.chains, []) AS chains, coalesce(m.taken, []) AS taken, coalesce(m.drops, 0) AS drops, coalesce(m.n_respawns, 0) AS respawns, coalesce(ag.clean, 0) AS aggro_clean, coalesce(ag.own, 0) AS aggro_own, coalesce(ps.passes, 0) AS passes)) AS mobs FROM (SELECT zone, name FROM m UNION DISTINCT SELECT zone, name FROM seen) k LEFT JOIN m ON m.zone = k.zone AND m.name = k.name LEFT JOIN ag ON ag.zone = k.zone AND ag.name = k.name LEFT JOIN ps ON ps.zone = k.zone AND ps.name = k.name LEFT JOIN z ON z.id = k.zone GROUP BY k.zone
